let currentLang = 'fa';

function setLanguage(lang) {
    if (!translations[lang]) return;
    currentLang = lang;
    
    // Update HTML attributes
    document.documentElement.lang = lang;
    document.documentElement.dir = (lang === 'fa') ? 'rtl' : 'ltr';
    
    // Update all text nodes with data-i18n
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (translations[lang][key]) {
            if (translations[lang][key].includes('<')) {
                el.innerHTML = translations[lang][key];
            } else {
                el.textContent = translations[lang][key];
            }
        }
    });
    
    // Update placeholders
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (translations[lang][key]) {
            el.setAttribute('placeholder', translations[lang][key]);
        }
    });

    // Update Globe Icon Language Switcher label
    const langCodeLabel = document.getElementById('langCodeLabel');
    if (langCodeLabel) {
        langCodeLabel.textContent = (lang === 'fa') ? 'EN' : 'فا';
    }

    // Update Locale Switcher active state (FA | EN)
    const langFaBtn = document.getElementById('langFaBtn');
    const langEnBtn = document.getElementById('langEnBtn');
    if (langFaBtn && langEnBtn) {
        if (lang === 'fa') {
            langFaBtn.classList.add('is-active', 'border-white/40', 'text-white', 'bg-white/10');
            langFaBtn.classList.remove('text-slate-400', 'border-transparent');
            langEnBtn.classList.remove('is-active', 'border-white/40', 'text-white', 'bg-white/10');
            langEnBtn.classList.add('text-slate-400', 'border-transparent');
        } else {
            langEnBtn.classList.add('is-active', 'border-white/40', 'text-white', 'bg-white/10');
            langEnBtn.classList.remove('text-slate-400', 'border-transparent');
            langFaBtn.classList.remove('is-active', 'border-white/40', 'text-white', 'bg-white/10');
            langFaBtn.classList.add('text-slate-400', 'border-transparent');
        }
    }

    // Refresh KPI Counter locale numbers if already counted
    const locale = (lang === 'fa') ? 'fa-IR' : 'en-US';
    const formatter = new Intl.NumberFormat(locale);
    document.querySelectorAll('.kpi-counter-val').forEach(counter => {
        const targetVal = parseFloat(counter.getAttribute('data-target') || '0');
        const kpiNum = counter.querySelector('.kpi-num') || counter;
        if (kpiNum.textContent !== '0') {
            if (lang === 'fa') {
                const formatted = formatter.format(targetVal);
                kpiNum.textContent = String(formatted).replace(/[0-9]/g, d => '۰۱۲۳۴۵۶۷۸۹'[d]);
            } else {
                kpiNum.textContent = formatter.format(targetVal);
            }
        }
    });

    try {
        localStorage.setItem('rahnab_lang', lang);
    } catch(e) {}
}

function initApp() {
    // 1. Language Switcher (Inspired by davidecattaneo.it: FA | EN)
    const langFaBtn = document.getElementById('langFaBtn');
    const langEnBtn = document.getElementById('langEnBtn');
    if (langFaBtn) langFaBtn.addEventListener('click', (e) => { e.preventDefault(); setLanguage('fa'); });
    if (langEnBtn) langEnBtn.addEventListener('click', (e) => { e.preventDefault(); setLanguage('en'); });

    // 2. Full-Screen Cinematic NavMenu Toggle (davidecattaneo.it style)
    const menuToggle = document.getElementById('navbarMenuToggle');
    const fullMenu = document.getElementById('fullNavMenu');
    const menuLinks = document.querySelectorAll('.navmenu-link, .submenu-link');
    const menuItems = document.querySelectorAll('.navmenu-item');
    const menuToggleLabel = document.getElementById('menuToggleLabel');
    const submenuToggleBtn = document.getElementById('submenuToggleBtn');
    const navmenuSubmenu = document.getElementById('navmenuSubmenu');

    if (submenuToggleBtn && navmenuSubmenu) {
        submenuToggleBtn.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            const isExpanded = submenuToggleBtn.getAttribute('aria-expanded') === 'true';
            if (isExpanded) {
                submenuToggleBtn.setAttribute('aria-expanded', 'false');
                submenuToggleBtn.classList.remove('is-active');
                navmenuSubmenu.classList.remove('is-open');
                navmenuSubmenu.style.maxHeight = '0';
            } else {
                submenuToggleBtn.setAttribute('aria-expanded', 'true');
                submenuToggleBtn.classList.add('is-active');
                navmenuSubmenu.classList.add('is-open');
                navmenuSubmenu.style.maxHeight = navmenuSubmenu.scrollHeight + 'px';
            }
        });
    }

    if (menuToggle && fullMenu) {
        const openMenu = () => {
            fullMenu.classList.remove('hidden');
            fullMenu.classList.add('flex');
            menuToggle.classList.add('is-active');
            menuToggle.setAttribute('aria-expanded', 'true');
            if (menuToggleLabel) {
                menuToggleLabel.textContent = (currentLang === 'fa') ? 'بستن' : 'CLOSE';
            }
            document.body.style.overflow = 'hidden';
            
            if (window.gsap) {
                gsap.fromTo(fullMenu, { opacity: 0 }, { opacity: 1, duration: 0.35, ease: 'power2.out' });
                gsap.fromTo(menuItems, 
                    { opacity: 0, y: 25 }, 
                    { opacity: 1, y: 0, duration: 0.5, stagger: 0.05, ease: 'power3.out', delay: 0.1 }
                );
            } else {
                fullMenu.classList.remove('opacity-0');
            }
        };

        const closeMenu = () => {
            menuToggle.classList.remove('is-active');
            menuToggle.setAttribute('aria-expanded', 'false');
            if (menuToggleLabel) {
                menuToggleLabel.textContent = (currentLang === 'fa') ? 'منو' : 'MENU';
            }
            if (submenuToggleBtn && navmenuSubmenu) {
                submenuToggleBtn.setAttribute('aria-expanded', 'false');
                submenuToggleBtn.classList.remove('is-active');
                navmenuSubmenu.classList.remove('is-open');
                navmenuSubmenu.style.maxHeight = '0';
            }
            if (window.gsap) {
                gsap.to(fullMenu, {
                    opacity: 0,
                    duration: 0.25,
                    ease: 'power2.in',
                    onComplete: () => {
                        fullMenu.classList.add('hidden');
                        fullMenu.classList.remove('flex');
                        document.body.style.overflow = '';
                    }
                });
            } else {
                fullMenu.classList.add('opacity-0');
                setTimeout(() => {
                    fullMenu.classList.add('hidden');
                    fullMenu.classList.remove('flex');
                    document.body.style.overflow = '';
                }, 250);
            }
        };

        menuToggle.addEventListener('click', (e) => {
            e.preventDefault();
            const isOpen = menuToggle.classList.contains('is-active');
            if (isOpen) {
                closeMenu();
            } else {
                openMenu();
            }
        });

        menuLinks.forEach(link => {
            link.addEventListener('click', () => {
                closeMenu();
            });
        });

        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && menuToggle.classList.contains('is-active')) {
                closeMenu();
            }
        });
    }

    // 3. Navbar Scrolled Glassmorphism on scroll
    const mainNav = document.getElementById('mainNavbar');
    if (mainNav) {
        window.addEventListener('scroll', () => {
            if (window.scrollY > 40) {
                mainNav.classList.add('navbar-scrolled');
            } else {
                mainNav.classList.remove('navbar-scrolled');
            }
        }, { passive: true });
    }

    // 3. B2B Modal Handling
    const modal = document.getElementById('inquiryModal');
    const openBtns = document.querySelectorAll('.btn-open-inquiry');
    const closeBtn = document.getElementById('closeModalBtn');

    if (modal) {
        openBtns.forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.preventDefault();
                modal.classList.remove('hidden');
                modal.classList.add('flex');
                setTimeout(() => modal.classList.remove('opacity-0'), 10);
                document.body.style.overflow = 'hidden';
            });
        });

        const closeModal = () => {
            modal.classList.add('opacity-0');
            setTimeout(() => {
                modal.classList.add('hidden');
                modal.classList.remove('flex');
            }, 300);
            document.body.style.overflow = '';
        };

        if (closeBtn) closeBtn.addEventListener('click', closeModal);

        modal.addEventListener('click', (e) => {
            if (e.target === modal) closeModal();
        });

        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && !modal.classList.contains('hidden')) {
                closeModal();
            }
        });

        const form = modal.querySelector('form');
        if (form) {
            form.addEventListener('submit', (e) => {
                e.preventDefault();
                alert(currentLang === 'fa' 
                    ? 'درخواست شما با موفقیت ثبت گردید. همکاران ما در معاونت سرمایه‌گذاری به زودی با شما تماس خواهند گرفت.'
                    : 'Your partnership inquiry has been submitted. Our team will contact you shortly.'
                );
                closeModal();
                form.reset();
            });
        }
    }

    // 4. Awwwards Trending Back to Top Button with Circular Progress Track
    const backToTopBtn = document.getElementById('backToTopBtn');
    const backToTopProgress = document.getElementById('backToTopProgress');
    if (backToTopBtn) {
        const updateScrollProgress = () => {
            const scrollY = window.scrollY;
            const maxScroll = document.documentElement.scrollHeight - window.innerHeight;
            if (scrollY > 350) {
                backToTopBtn.classList.add('visible');
            } else {
                backToTopBtn.classList.remove('visible');
            }
            if (backToTopProgress && maxScroll > 0) {
                const progress = Math.min(1, Math.max(0, scrollY / maxScroll));
                // Circumference for r=21 is 132px (2 * Math.PI * 21)
                const offset = 132 - (progress * 132);
                backToTopProgress.style.strokeDashoffset = String(offset);
            }
        };

        window.addEventListener('scroll', updateScrollProgress, { passive: true });
        updateScrollProgress();

        backToTopBtn.addEventListener('click', () => {
            window.scrollTo({ top: 0, behavior: 'smooth' });
        });
    }

    // Initialize dynamic cursor spotlight tracking on cards
    initCardSpotlights();

    // Restore saved language preference
    try {
        const saved = localStorage.getItem('rahnab_lang');
        if (saved && (saved === 'fa' || saved === 'en')) {
            setLanguage(saved);
        }
    } catch(e) {}
}

function initCardSpotlights() {
    const cards = document.querySelectorAll('.subsidiary-card, .service-card');
    cards.forEach(card => {
        card.addEventListener('mousemove', (e) => {
            const rect = card.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;
            card.style.setProperty('--mouse-x', `${x}px`);
            card.style.setProperty('--mouse-y', `${y}px`);
        });
    });
}

window.initApp = initApp;
